// And groups predicates with the AND operator between them.
func And(predicates ...predicate.AutomationScript) predicate.AutomationScript {
	return predicate.AutomationScript(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.AutomationScript) predicate.AutomationScript {
	return predicate.AutomationScript(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.AutomationScript) predicate.AutomationScript {
	return predicate.AutomationScript(sql.NotPredicates(p))
}
